      {:error, :expired} ->
        {:error, :expired}
    end
end

def verify(context, salt, token, opts \\ []) when is_binary(salt) do
  case context.decode(token) do
    {:ok, claims} ->
      case context.verify(claims, opts) do
        true -> {:ok, claims["user_id"]}
        false -> {:error, :invalid}
      end
    {:error, _reason} ->
      {:error, :expired}
    _ ->
      {:error, :missing}
  end
end
